// Generates the Freeze Day set: 1,000 fictional messages from the
// morning after a hard freeze, with an answer key, into
// evals/freeze-day.jsonl. Deterministic (fixed seed), so the file can be
// regenerated byte for byte. No model is involved: every message comes
// from the templates below, and every phone number is in the reserved
// fictional 555-01xx range.
//
// Answer key per line: group (messages that truly belong together, or
// null), kind (same_job | shared_cause | null), category, urgency
// (null where the template leaves it open).
//
// Run: node scripts/gen-freeze.mjs [--n=1000]

import { writeFileSync } from "node:fs";

const N = Number((process.argv.find((a) => a.startsWith("--n=")) ?? "--n=1000").slice(4));

let seed = 2021_02_15;
const rand = () => {
  seed |= 0;
  seed = (seed + 0x6d2b79f5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
};
const pick = (a) => a[Math.floor(rand() * a.length)];
const chance = (p) => rand() < p;

const FIRST = ["Maria", "Jose", "Linda", "James", "Rosa", "Carlos", "Ana", "David", "Patricia", "Luis", "Sandra", "Miguel", "Karen", "Juan", "Nancy", "Robert", "Elena", "Michael", "Gloria", "Daniel", "Teresa", "Brian", "Lucia", "Kevin", "Diana", "Ricardo", "Amy", "Javier", "Melissa", "Tom", "Sofia", "Eric", "Veronica", "Ray", "Monica", "Gabe", "Irene", "Sam", "Yolanda", "Ken", "Priya", "Marcus", "Tina", "Hector", "Beth", "Omar", "Carmen", "Derek", "Alma", "Victor", "Jen", "Arturo", "Kim", "Raul", "Debbie", "Ernesto", "Angela", "Felipe", "Laura", "Andre"];
const LAST = ["Garcia", "Martinez", "Hernandez", "Lopez", "Gonzalez", "Rodriguez", "Perez", "Sanchez", "Ramirez", "Torres", "Flores", "Rivera", "Gomez", "Diaz", "Reyes", "Cruz", "Morales", "Ortiz", "Gutierrez", "Chavez", "Smith", "Johnson", "Williams", "Brown", "Jones", "Miller", "Davis", "Wilson", "Anderson", "Taylor", "Thomas", "Moore", "Jackson", "White", "Harris", "Martin", "Thompson", "Nguyen", "Tran", "Patel", "Kim", "Okafor", "Bauer", "Price", "Mendez", "Salinas", "Villarreal", "Trevino", "Cantu", "Guerra"];
const AREAS = ["Calallen", "Flour Bluff", "Southside", "Annaville", "Padre Island", "Downtown", "Bay Area", "Westside", "Northwest", "Robstown"];
const STREETS = [
  ["Mesquite", "St"], ["Laguna", "Dr"], ["Holly", "Rd"], ["Weber", "Rd"], ["Staples", "St"], ["Alameda", "St"],
  ["Yorktown", "Blvd"], ["Everhart", "Rd"], ["Saratoga", "Blvd"], ["Kostoryz", "Rd"], ["Gollihar", "Rd"], ["Ayers", "St"],
  ["Baldwin", "Blvd"], ["Airline", "Rd"], ["Rodd Field", "Rd"], ["Ocean", "Dr"], ["Santa Fe", "St"], ["Morgan", "Ave"],
  ["Doddridge", "St"], ["McArdle", "Rd"], ["Carroll", "Ln"], ["Cimarron", "Blvd"], ["Lipes", "Blvd"], ["Williams", "Dr"],
  ["Up River", "Rd"], ["Leopard", "St"], ["Agnes", "St"], ["Navigation", "Blvd"], ["Waldron", "Rd"], ["Purdue", "Rd"],
  ["Flynn", "Pkwy"], ["Tiger", "Ln"], ["Brawner", "Pkwy"], ["Del Mar", "Blvd"], ["Sunnybrook", "Rd"], ["Kingston", "Dr"],
  ["Nile", "Dr"], ["Pharaoh", "Dr"], ["Cayo", "Ct"], ["Whiteley", "Dr"], ["Glenoak", "Dr"], ["Bonner", "Dr"],
];
const AREA_CODES = ["361", "512", "210", "713", "956", "830", "979", "254", "409", "432", "281", "915"];

const phonePool = [];
for (const ac of AREA_CODES) for (let n = 0; n < 100; n++) phonePool.push(`${ac}-555-01${String(n).padStart(2, "0")}`);
for (let i = phonePool.length - 1; i > 0; i--) {
  const j = Math.floor(rand() * (i + 1));
  [phonePool[i], phonePool[j]] = [phonePool[j], phonePool[i]];
}
let phoneNext = 0;
const newPhone = () => {
  if (phoneNext >= phonePool.length) throw new Error("phone pool exhausted");
  return phonePool[phoneNext++];
};

const usedAddr = new Set();
const newAddress = (streetPair) => {
  for (;;) {
    const s = streetPair ?? pick(STREETS);
    const num = 100 + Math.floor(rand() * 5800);
    const key = `${num} ${s[0]}`;
    if (usedAddr.has(key)) continue;
    usedAddr.add(key);
    return { num, street: s[0], suffix: s[1], text: `${num} ${s[0]} ${s[1]}` };
  }
};

const person = (streetPair) => {
  const first = pick(FIRST);
  return { first, last: pick(LAST), phone: newPhone(), addr: newAddress(streetPair), area: pick(AREAS) };
};
const name = (p) => (chance(0.75) ? `${p.first} ${p.last}` : p.first);
const fill = (t, p, extra = {}) =>
  t
    .replaceAll("{name}", name(p))
    .replaceAll("{first}", p.first)
    .replaceAll("{addr}", p.addr.text)
    .replaceAll("{num}", String(p.addr.num))
    .replaceAll("{street}", p.addr.street)
    .replaceAll("{area}", p.area)
    .replaceAll("{phone}", p.phone)
    .replace(/\{(\w+)\}/g, (m, k) => (k in extra ? String(extra[k]) : m));

const ROOMS = ["hall bathroom", "kitchen", "laundry room", "garage", "master bath", "utility closet"];
const CUARTOS = ["baño", "cocina", "cuarto de lavado", "garaje"];
const ELDERS = [["mom", "mamá"], ["dad", "papá"], ["grandmother", "abuela"], ["father-in-law", "suegro"]];

// [template, urgency, problem label (EN), problem label (ES)]
const FIRSTS = {
  emergency: [
    ["Pipe burst in the {room}, water spraying everywhere and I can't find the shut off. {addr}. {name} {phone}", "burst pipe", "tubo reventado"],
    ["HELP water pouring through the ceiling, a pipe in the attic must have burst. {addr}, {area}. {name} {phone}", "pipe in the attic", "tubo del ático"],
    ["Frozen pipe split under the kitchen sink, water all over the floor. Turned the main off but need someone today. {name}, {addr}, {phone}", "split pipe", "tubo partido"],
    ["No heat since last night and my {elder} is {age}, house is {temp} degrees inside. {addr} {phone} - {first}", "no heat", "falta de calefacción"],
    ["Water heater tank burst in the garage, water running out under the door. {addr}. call {phone} {first}", "water heater", "calentador"],
    ["Se reventó un tubo en el {cuarto} y sale agua por todos lados. {addr}, {area}. {name} {phone}", "burst pipe", "tubo reventado"],
    ["No tenemos calefacción desde anoche y mi {elder_es} tiene {age} años. Hace mucho frío en la casa. {addr}. {phone}", "no heat", "falta de calefacción"],
  ],
  "same-day": [
    ["No water at all this morning, I think the pipes froze. {addr}. {phone} {first}", "frozen pipes", "tuberías congeladas"],
    ["Water heater won't light since the power came back, no hot water. {name}, {area}, {phone}", "water heater", "calentador"],
    ["Heat pump is blowing cold air and the house keeps getting colder. {name} {phone} {area}", "heat pump", "bomba de calor"],
    ["Kitchen pipes frozen, nothing comes out of the faucet. Bathroom still works. {addr} {name} {phone}", "frozen kitchen pipes", "tuberías congeladas"],
    ["Toilet won't fill and there's no water pressure since the freeze. {first} at {addr}, {phone}", "no water pressure", "falta de presión"],
    ["Se congelaron las tuberías y no sale agua. {addr}. {name} {phone}", "frozen pipes", "tuberías congeladas"],
    ["El calentador de agua no prende desde que regresó la luz. {name}, {area}. {phone}", "water heater", "calentador"],
  ],
  routine: [
    ["Outside faucet cracked from the cold and drips a little. Not urgent, whenever you can. {name} {phone}", "outside faucet", "llave de afuera"],
    ["Can I get a quote to insulate the pipes under my house before the next freeze? {name}, {area}, {phone}", "pipe insulation quote", "cotización"],
    ["Looking to have a tankless water heater installed sometime next month. {name} {phone}", "tankless install", "instalación"],
    ["Do you sell faucet covers or pipe insulation? {first}, {area}, {phone}", "faucet covers", "cubiertas"],
    ["Want someone to check our sprinkler backflow after the freeze, no rush. {name} {addr} {phone}", "backflow check", "revisión"],
    ["Quisiera una cotización para aislar las tuberías antes de la próxima helada. {name}, {area}. {phone}", "pipe insulation quote", "cotización"],
  ],
};
const HAZARDS = [
  "I smell gas near the furnace since we turned it back on. {addr} {phone} {first}",
  "CO alarm going off, we had a space heater running all night. Everyone is outside. {addr}, {name} {phone}",
  "Huele a gas en la cocina desde anoche. {addr}. {name} {phone}",
];
const SPAM = [
  ["WINTER STORM BLOWOUT! Portable generators 50% off today only. Reply YES to reserve!", "spam"],
  ["This is an urgent message about your vehicle's extended warranty. Press 1 to speak to a specialist.", "spam"],
  ["Grow your plumbing business with exclusive storm leads! $25 per lead, guaranteed. Reply STOP to opt out.", "spam"],
  ["hey is this {first}? you left your jacket at my place lol", "not-a-lead"],
  ["ok thanks", "not-a-lead"],
  ["wrong number sorry", "not-a-lead"],
];
// Follow-ups from the same household. {phone} = original sender; {phone2} = a new number.
const FOLLOWUPS = [
  { t: "Me again at {addr}, the {problem} is still not fixed, please hurry. {phone}", samePhone: true },
  { t: "This is {other}, {first}'s {rel}, about the {problem} at {num} {street}. Any ETA? {phone2}", samePhone: false },
  { t: "Still waiting on someone for the {problem}. {phone}", samePhone: true },
  { t: "Calling for my {rel2} {first} at {addr}, they messaged you earlier about the {problem}. I'm {other}, {phone2}", samePhone: false },
  { t: "Soy {other}, familiar de {first}, por lo del {problem_es} en {num} {street}. ¿A qué hora vienen? {phone2}", samePhone: false },
  { t: "Following up for {first} {last} about the {problem} on {street}, nobody has called back yet. {other} {phone2}", samePhone: false },
];
const CLUSTER = [
  "No water since about {time} at {addr}. My neighbor says theirs is out too. Is it the city? {first} {phone}",
  "Whole street on {street} has no water?? {addr}. nothing from any faucet. {first} {phone}",
  "Hola, no tenemos agua desde la mañana en la calle {street}, {addr}. Mis vecinos tampoco. {first} {phone}",
  "Water pressure dropped to nothing at {addr} around {time}, and the house next door is the same. {name} {phone}",
  "Everybody on our block of {street} lost water this morning. {addr}, {name}, {phone}",
];
const TIMES = ["5:30", "6am", "6:15", "6:45", "7am"];
const RELS = ["husband", "wife", "son", "daughter", "tenant", "neighbor"];

const firstExtras = () => {
  const [en, es] = pick(ELDERS);
  return { room: pick(ROOMS), cuarto: pick(CUARTOS), elder: en, elder_es: es, age: 70 + Math.floor(rand() * 22), temp: 45 + Math.floor(rand() * 10) };
};

const messages = []; // { text, group, kind, category, urgency, order }
let groupSeq = 0;

// Shared-cause clusters: 3-5 homes on one street.
const clusterStreets = [...STREETS].sort(() => rand() - 0.5).slice(0, 12);
for (const s of clusterStreets) {
  const g = `cause-${++groupSeq}`;
  const size = 3 + Math.floor(rand() * 3);
  const time = pick(TIMES);
  for (let k = 0; k < size; k++) {
    const p = person(s);
    messages.push({ text: fill(pick(CLUSTER), p, { time }), group: g, kind: "shared_cause", category: "real", urgency: "same-day", order: rand() });
  }
}

// Households that write more than once (same_job).
for (let h = 0; h < 72; h++) {
  const g = `job-${++groupSeq}`;
  const p = person();
  const urgency = chance(0.6) ? "emergency" : "same-day";
  const [tpl, problem, problemEs] = pick(FIRSTS[urgency]);
  const t0 = rand() * 0.7;
  messages.push({ text: fill(tpl, p, firstExtras()), group: g, kind: "same_job", category: "real", urgency, order: t0 });
  const extra = chance(0.25) ? 2 : 1;
  for (let k = 0; k < extra; k++) {
    const f = pick(FOLLOWUPS);
    const other = pick(FIRST);
    const text = fill(f.t, p, { problem, problem_es: problemEs, other, rel: pick(RELS), rel2: pick(["mom", "dad", "sister", "brother", "grandma"]), phone2: newPhone(), last: p.last });
    messages.push({ text, group: g, kind: "same_job", category: "real", urgency, order: t0 + 0.05 + rand() * 0.25 });
  }
}

// Hazards, spam / not-a-lead.
for (let i = 0; i < 12; i++) {
  const p = person();
  messages.push({ text: fill(pick(HAZARDS), p), group: null, kind: null, category: "real", urgency: "emergency", order: rand() });
}
for (let i = 0; i < 55; i++) {
  const [t, cat] = pick(SPAM);
  messages.push({ text: fill(t, person()), group: null, kind: null, category: cat, urgency: null, order: rand() });
}

// Singles fill the rest. Some share a street with a cluster (hard negatives).
while (messages.length < N) {
  const r = rand();
  const urgency = r < 0.3 ? "emergency" : r < 0.75 ? "same-day" : "routine";
  const street = chance(0.15) ? pick(clusterStreets) : null;
  const p = person(street);
  const [tpl] = pick(FIRSTS[urgency]);
  messages.push({ text: fill(tpl, p, firstExtras()), group: null, kind: null, category: "real", urgency: tpl.includes("{elder") ? null : urgency, order: rand() });
}

messages.sort((a, b) => a.order - b.order);
const out = messages.slice(0, N).map((m, i) => JSON.stringify({ id: i + 1, text: m.text, group: m.group, kind: m.kind, category: m.category, urgency: m.urgency }));
writeFileSync("evals/freeze-day.jsonl", out.join("\n") + "\n");
const groups = new Map();
for (const m of messages.slice(0, N)) if (m.group) groups.set(m.group, (groups.get(m.group) ?? 0) + 1);
console.log(`wrote ${out.length} messages · ${[...groups.keys()].filter((g) => g.startsWith("job")).length} multi-message households · ${[...groups.keys()].filter((g) => g.startsWith("cause")).length} shared-cause clusters · phones used ${phoneNext}`);
